import { useEffect } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';

import { getNavigationAllowlist } from 'config/navigationAllowlist';
import { resolveSafeLocation } from 'utils/safeNavigation';

const DEFAULT_FALLBACK_PATH = '/value-creation';

export const SafeLocationGuard = (): null => {
  const { pathname, search } = useLocation();
  const navigate = useNavigate();

  useEffect(() => {
    const safe = resolveSafeLocation(
      pathname,
      search,
      getNavigationAllowlist(),
    );

    if (!safe) {
      navigate(DEFAULT_FALLBACK_PATH, { replace: true });
      return;
    }

    const needsCorrection =
      safe.pathname !== pathname || safe.search !== search;

    if (needsCorrection) {
      navigate(
        safe.search
          ? { pathname: safe.pathname, search: safe.search }
          : safe.pathname,
        { replace: true },
      );
    }
  }, [pathname, search, navigate]);

  return null;
};
